package net.civeira.phylax.features.oauth.user.domain;

import java.util.Optional;

import lombok.Getter;

/**
 * Result of a user registration request.
 *
 * Responsibilities: - Represent registration outcomes and username. - Provide factory methods for
 * common statuses.
 *
 * Design notes: - Immutable value object with static factories. - Used by registration flows and
 * UI.
 */
@Getter
public class RegistrationResult {

  /**
   * Status of the registration process.
   */
  public enum Status {
    OK, PENDING, CANCEL
  }

  /**
   * Registration status.
   */
  private final Status status;
  /**
   * Username when registration succeeds immediately (Status.OK).
   */
  private final String username;
  /**
   * Notification data to send when status is PENDING (email verification required).
   */
  private final RegistrationNotificationData notificationData;

  /**
   * Builds a successful registration result.
   *
   * Sets the status to OK and includes username. Used when registration is immediately activated.
   *
   * @param username registered username
   * @return registration result
   */
  public static RegistrationResult ok(String username) {
    return new RegistrationResult(Status.OK, username, null);
  }

  /**
   * Builds a pending registration result with notification data.
   *
   * Sets the status to PENDING. The caller must deliver the verification email using the returned
   * notification data.
   *
   * @param notificationData data required to send the verification email
   * @return registration result
   */
  public static RegistrationResult pending(RegistrationNotificationData notificationData) {
    return new RegistrationResult(Status.PENDING, null, notificationData);
  }

  /**
   * Builds a pending registration result without notification data.
   *
   * Use when the adapter handles notification internally.
   *
   * @return registration result
   */
  public static RegistrationResult pending() {
    return new RegistrationResult(Status.PENDING, null, null);
  }

  /**
   * Builds a cancelled registration result.
   *
   * Sets the status to CANCEL without username. Used when registration cannot be completed.
   *
   * @return registration result
   */
  public static RegistrationResult cancel() {
    return new RegistrationResult(Status.CANCEL, null, null);
  }

  /**
   * Returns the notification data to be delivered when status is PENDING.
   *
   * @return optional notification data
   */
  public Optional<RegistrationNotificationData> getNotificationData() {
    return Optional.ofNullable(notificationData);
  }

  private RegistrationResult(Status status, String username,
      RegistrationNotificationData notificationData) {
    this.status = status;
    this.username = username;
    this.notificationData = notificationData;
  }
}
